from __future__ import annotations

"""Apply internal handoff rules before CRM or email side effects run."""

from zoom_models import (
    FILE_STATUS_COMPLETED,
    RecordingHandoffWebhook,
    describe_playback_risk_failed,
)

HANDOFF_REASON_READY = "artifacts_verified"
HANDOFF_REASON_WAIT = "processing_incomplete"
HANDOFF_REASON_BLOCKED = "transcode_failed"


def _session_allows_publish(webhook: RecordingHandoffWebhook) -> bool:
    # Participant: also require file_processing_status == FILE_STATUS_COMPLETED.
    return webhook.is_session_finished()


def evaluate_recording_handoff(webhook: RecordingHandoffWebhook) -> dict[str, object]:
    if webhook.file_failed():
        return {
            "recording_uuid": webhook.recording_uuid,
            "meeting_uuid": webhook.meeting_uuid,
            "host_user_id": webhook.host_user_id,
            "ready_for_handoff": False,
            "crm_safe_to_link": False,
            "reason": HANDOFF_REASON_BLOCKED,
            "correlation_id": webhook.correlation_id,
            "detail": describe_playback_risk_failed(),
        }

    session_ok = _session_allows_publish(webhook)
    file_ok = webhook.file_processing_status == FILE_STATUS_COMPLETED

    if session_ok and file_ok:
        reason = HANDOFF_REASON_READY
    elif session_ok:
        reason = HANDOFF_REASON_WAIT
    else:
        reason = HANDOFF_REASON_WAIT

    publish_ok = session_ok and file_ok
    # Starter couples CRM to session-only readiness; file pipeline can still be running.
    crm_ok = session_ok

    return {
        "recording_uuid": webhook.recording_uuid,
        "meeting_uuid": webhook.meeting_uuid,
        "host_user_id": webhook.host_user_id,
        "ready_for_handoff": publish_ok,
        "crm_safe_to_link": crm_ok,
        "reason": reason,
        "correlation_id": webhook.correlation_id,
        "detail": "",
    }


def summarize_recording_handoffs(results: list[dict[str, object]]) -> dict[str, object]:
    ready_n = sum(1 for row in results if row["ready_for_handoff"])
    blocked = sum(1 for row in results if row["reason"] == HANDOFF_REASON_BLOCKED)
    waiting = sum(1 for row in results if row["reason"] == HANDOFF_REASON_WAIT)
    return {
        "event_count": len(results),
        "ready_count": ready_n,
        "blocked_count": blocked,
        "waiting_count": waiting,
        "results": results,
    }


class RecordingHandoffWorkflow:
    def __init__(self) -> None:
        self.history: list[dict[str, object]] = []

    def handle(self, webhook: RecordingHandoffWebhook) -> dict[str, object]:
        outcome = evaluate_recording_handoff(webhook)
        self.history.append(outcome)
        return outcome

    def summarize(self) -> dict[str, object]:
        return summarize_recording_handoffs(self.history)


def pipeline_health_snapshot(results: list[dict[str, object]]) -> str:
    if not results:
        return "idle"
    if any(row["ready_for_handoff"] for row in results):
        return "shipping"
    if any(row["reason"] == HANDOFF_REASON_BLOCKED for row in results):
        return "needs_ops"
    return "backlog"

