from __future__ import annotations

from dataclasses import dataclass

SESSION_STATUS_STOPPED = "stopped"
SESSION_STATUS_COMPLETED = "completed"

FILE_STATUS_PROCESSING = "processing"
FILE_STATUS_COMPLETED = "completed"
FILE_STATUS_FAILED = "failed"

ALLOWED_SESSION = {SESSION_STATUS_STOPPED, SESSION_STATUS_COMPLETED}
ALLOWED_FILE = {FILE_STATUS_PROCESSING, FILE_STATUS_COMPLETED, FILE_STATUS_FAILED}


def _non_empty(label: str, value: str) -> None:
    if not value or not str(value).strip():
        raise ValueError(f"{label} required")


@dataclass(frozen=True)
class RecordingHandoffWebhook:
    """Normalized shape of what your worker stores from Zoom cloud recording callbacks."""

    recording_uuid: str
    meeting_uuid: str
    host_user_id: str
    session_status: str
    file_processing_status: str
    total_bytes: int
    correlation_id: str

    def __post_init__(self) -> None:
        _non_empty("recording_uuid", self.recording_uuid)
        _non_empty("meeting_uuid", self.meeting_uuid)
        _non_empty("host_user_id", self.host_user_id)
        _non_empty("correlation_id", self.correlation_id)
        ss = self.session_status.strip()
        fs = self.file_processing_status.strip()
        if ss not in ALLOWED_SESSION:
            raise ValueError("unsupported session_status")
        if fs not in ALLOWED_FILE:
            raise ValueError("unsupported file_processing_status")
        if self.total_bytes < 0:
            raise ValueError("total_bytes must be non-negative")
        object.__setattr__(self, "session_status", ss)
        object.__setattr__(self, "file_processing_status", fs)

    def handoff_subject(self) -> str:
        return f"{self.meeting_uuid}/{self.recording_uuid}"

    def is_session_finished(self) -> bool:
        return self.session_status in {SESSION_STATUS_STOPPED, SESSION_STATUS_COMPLETED}

    def file_failed(self) -> bool:
        return self.file_processing_status == FILE_STATUS_FAILED


def describe_playback_risk_failed() -> str:
    return "do_not_publish_failed_transcode"


def normalize_correlation(correlation_id: str) -> str:
    return correlation_id.strip()


def bytes_to_mb_hint(total_bytes: int) -> float:
    if total_bytes < 0:
        raise ValueError("total_bytes must be non-negative")
    return total_bytes / (1024 * 1024)


def webhook_pair_key(meeting_uuid: str, recording_uuid: str) -> str:
    return f"{meeting_uuid.strip()}|{recording_uuid.strip()}"

